  "inlineSchema": "// Joylinks IT akademiyasi — ma'lumotlar bazasi sxemasi\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ─────────────────────────────────────────────\n// Enums\n// ─────────────────────────────────────────────\n\nenum CourseLevel {\n  BEGINNER\n  INTERMEDIATE\n  ADVANCED\n}\n\nenum CourseFormat {\n  OFFLINE\n  ONLINE\n  HYBRID\n}\n\nenum ApplicationStatus {\n  NEW\n  CONTACTED\n  ENROLLED\n  REJECTED\n}\n\n// ─────────────────────────────────────────────\n// Admin\n// ─────────────────────────────────────────────\n\nmodel Admin {\n  id        String   @id @default(cuid())\n  email     String   @unique\n  password  String\n  name      String\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ─────────────────────────────────────────────\n// Kurslar va mentorlar\n// ─────────────────────────────────────────────\n\nmodel Course {\n  id               String        @id @default(cuid())\n  slug             String        @unique\n  title            String\n  shortDescription String\n  description      String\n  image            String?\n  icon             String        @default(\"code\")\n  color            String        @default(\"#0eb182\")\n  durationMonths   Int\n  lessonsPerWeek   Int           @default(3)\n  lessonHours      Int           @default(2)\n  price            Int\n  oldPrice         Int?\n  level            CourseLevel   @default(BEGINNER)\n  format           CourseFormat  @default(OFFLINE)\n  skills           String[]\n  /// [{ title: string, topics: string[] }]\n  curriculum       Json          @default(\"[]\")\n  isPopular        Boolean       @default(false)\n  isPublished      Boolean       @default(true)\n  order            Int           @default(0)\n  mentors          Mentor[]\n  applications     Application[]\n  createdAt        DateTime      @default(now())\n  updatedAt        DateTime      @updatedAt\n\n  @@index([isPublished, order])\n}\n\nmodel Mentor {\n  id              String   @id @default(cuid())\n  fullName        String\n  position        String\n  bio             String?\n  photo           String?\n  experienceYears Int      @default(1)\n  studentsCount   Int      @default(0)\n  skills          String[]\n  telegram        String?\n  instagram       String?\n  linkedin        String?\n  isActive        Boolean  @default(true)\n  order           Int      @default(0)\n  courses         Course[]\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  @@index([isActive, order])\n}\n\n// ─────────────────────────────────────────────\n// Ijtimoiy isbot: bitiruvchilar fikri va hamkorlar\n// ─────────────────────────────────────────────\n\nmodel Testimonial {\n  id          String   @id @default(cuid())\n  fullName    String\n  photo       String?\n  courseName  String\n  workplace   String?\n  position    String?\n  text        String\n  rating      Int      @default(5)\n  videoUrl    String?\n  isPublished Boolean  @default(true)\n  order       Int      @default(0)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@index([isPublished, order])\n}\n\nmodel Partner {\n  id        String   @id @default(cuid())\n  name      String\n  logo      String?\n  website   String?\n  isActive  Boolean  @default(true)\n  order     Int      @default(0)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ─────────────────────────────────────────────\n// Kontent: FAQ, filiallar, yangiliklar\n// ─────────────────────────────────────────────\n\nmodel Faq {\n  id          String   @id @default(cuid())\n  question    String\n  answer      String\n  isPublished Boolean  @default(true)\n  order       Int      @default(0)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n\nmodel Branch {\n  id           String   @id @default(cuid())\n  name         String\n  address      String\n  landmark     String?\n  phone        String\n  workingHours String   @default(\"Du–Sha: 09:00 – 21:00\")\n  mapUrl       String?\n  image        String?\n  isActive     Boolean  @default(true)\n  order        Int      @default(0)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n}\n\nmodel Post {\n  id          String   @id @default(cuid())\n  slug        String   @unique\n  title       String\n  excerpt     String\n  content     String\n  cover       String?\n  isPublished Boolean  @default(true)\n  publishedAt DateTime @default(now())\n  views       Int      @default(0)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@index([isPublished, publishedAt])\n}\n\n// ─────────────────────────────────────────────\n// Arizalar (saytdan kelgan so'rovlar)\n// ─────────────────────────────────────────────\n\nmodel Application {\n  id        String            @id @default(cuid())\n  fullName  String\n  phone     String\n  message   String?\n  status    ApplicationStatus @default(NEW)\n  note      String?\n  course    Course?           @relation(fields: [courseId], references: [id], onDelete: SetNull)\n  courseId  String?\n  createdAt DateTime          @default(now())\n  updatedAt DateTime          @updatedAt\n\n  @@index([status, createdAt])\n}\n\n// ─────────────────────────────────────────────\n// Sayt sozlamalari (yagona yozuv, id = 1)\n// ─────────────────────────────────────────────\n\nmodel SiteSettings {\n  id                Int      @id @default(1)\n  heroBadge         String   @default(\"Yangi guruhlarga qabul ochiq\")\n  heroTitle         String   @default(\"Kelajak kasbini Joylinks bilan egallang\")\n  heroSubtitle      String   @default(\"Amaliyotga yo'naltirilgan IT kurslar, tajribali mentorlar va ishga joylashishda yordam.\")\n  phone             String   @default(\"+998 71 200 00 00\")\n  email             String   @default(\"info@joylinks.uz\")\n  address           String   @default(\"Toshkent sh.\")\n  telegram          String?\n  instagram         String?\n  youtube           String?\n  facebook          String?\n  graduatesCount    Int      @default(5000)\n  employmentRate    Int      @default(87)\n  mentorsCount      Int      @default(40)\n  yearsOfExperience Int      @default(6)\n  updatedAt         DateTime @updatedAt\n}\n",
